-- Poonawalla Fincorp September 2026 attendance, from the consolidated review workbook
-- (Sept_2026_Attendance_Consolidated.xlsx; calendar September, day columns 1-30).
-- Replaces September entries only for the employee-site pairs present in the workbook.
-- Sheet codes: P=present (also worked holiday / worked weekly-off), H=paid holiday not
-- worked, W=weekly off, A=absent, L=leave, .=no entry. Reliever pairs store duty as ED.
BEGIN;
SET LOCAL app.attendance_source='import';
CREATE TEMP TABLE pfl(c uuid, u uuid, emp text, s text, rel boolean);
DELETE FROM attendance_entries ae USING pfl
 WHERE ae.candidate_id=pfl.c AND ae.unit_id=pfl.u
   AND ae.entry_date BETWEEN '2026-09-01' AND '2026-09-30';
 SELECT pfl.u, pfl.c, 'aad77ba7-98d2-44cb-a0f1-b598eed740f4',
        CASE WHEN ch='P' AND NOT pfl.rel THEN 8 ELSE 0 END,
        pfl.rel,
        '2026-09-01'::date + i-1,
        CASE WHEN pfl.rel THEN ''
             ELSE CASE ch WHEN 'P' THEN 'P' WHEN 'H' THEN 'PH' WHEN 'W' THEN 'WO'
                          WHEN 'A' THEN 'A' WHEN 'L' THEN 'L' END END,
        CASE WHEN pfl.rel AND ch='P' THEN 1 ELSE 0 END
 FROM pfl CROSS JOIN LATERAL (SELECT i, substr(pfl.s,i,1) ch FROM generate_series(1,30) i) d
 WHERE ch <> '.' AND (NOT pfl.rel OR ch='P');
COMMIT;
